import { definePlugin, f, Field, validateInput, forbidden, validationError } from '#calm';
import { createRoles, OWNER } from './roles.js';
import { createTeams, isId } from './teams.js';

// Teams (organizations, workspaces): members with roles, email invitations, and team-scoped
// resources, the multi-tenancy almost every SaaS needs.
//
//   resource('project', { team: true, fields, policy: { list: 'member', read: 'member', create: 'member', update: 'team:admin', delete: 'team:admin' } })
//
// A team-scoped resource gets a `team` field (f.ref('team'), immutable) and these guarantees,
// whatever its policies say:
//  - Every query is scoped to the teams the caller belongs to (the service scope()), so records of
//    other teams are invisible: lists skip them and ids answer 404, guessed or not. Global admins
//    are no exception: tenants stay apart (use { system: true } in your own admin tooling).
//  - Creating needs membership in the target team (body `team`, else the X-Team header).
//  - Records never move to another team (immutable field, also enforced for service calls).
//
// Policies, usable in resources and routes ('member | admin', visibleTo('team:admin')...):
//   'member'        anyone in the team          'team:<role>'  that role or above
// The team is the record's team, else :teamId in the path, else (create) body.team, else the
// X-Team header, else (list) ?team=. With a record in hand, only the record's team counts.

const TEAM_FIELD = 'team';

export default definePlugin({
  name: 'teams',
  options: {
    /** Roles from most to least powerful. Must start with 'owner', 'admin'; add your own after them. */
    roles: ['owner', 'admin', 'member'],
    /** Role of an invitation that does not say. */
    defaultRole: 'member',
    /** Who may create teams (any policy, e.g. 'admin'). */
    createPolicy: 'authenticated',
    /** Lowest team role that may invite (and list, resend, revoke invitations). 'member': everyone in the team. */
    inviteRole: 'admin',
    invitationTtlDays: 7,
    /** Open (pending or expired) invitations one team may have. 0: no limit. */
    maxOpenInvitations: 100,
    /** Minimum time between two sends of the same invitation. */
    resendCooldownSeconds: 60,
    /** Page of your frontend that reads ?token= and calls /accept. Default: APP_URL + '/invite'. */
    linkUrl: null,
    /**
     * A field of your user resource that is truthy once the account's email is verified (e.g.
     * 'emailVerifiedAt'). When set, verified users see their invitations and accept them without
     * the link. Leave null unless you verify emails: CalmAPI does not, by default.
     */
    verifiedEmailField: null,
    /** Members see each other's email addresses in GET /teams/:teamId/members. */
    showMemberEmails: true,
    /** Teams one person may own. 0: no limit. */
    maxOwnedTeams: 20,
    /** Deleting a team deletes its records in team-scoped resources. */
    deleteRecords: true,
    /** Header naming the active team. */
    header: 'x-team',
  },
  setup(calm, options) {
    const roles = createRoles(options.roles);
    if (!roles.has(options.defaultRole)) throw new Error(`teams: defaultRole "${options.defaultRole}" is not one of ${roles.list.join(', ')}`);
    if (!roles.has(options.inviteRole)) throw new Error(`teams: inviteRole "${options.inviteRole}" is not one of ${roles.list.join(', ')}`);
    const header = String(options.header).toLowerCase();
    const teams = createTeams(calm, options, roles);
    const { memberships, known } = teams;
    const scoped = new Set(); // names of team-scoped resources

    // ---- team-scoped resources ----------------------------------------------------------

    calm.onResource((def) => {
      if (!def.options.team) return def;
      if (def.options.team !== true) throw new Error(`${def.name}: use team: true (the field is always "${TEAM_FIELD}")`);
      if (def.name === 'team') throw new Error('The team resource cannot be team-scoped');
      const declared = def.fields[TEAM_FIELD];
      if (declared && (declared.type !== 'ref' || declared.opts.ref !== 'team')) throw new Error(`${def.name}: "${TEAM_FIELD}" must be f.ref('team') on a team-scoped resource`);
      if (def.ownerField === TEAM_FIELD) throw new Error(`${def.name}: "${TEAM_FIELD}" cannot be the owner field`);
      const base = declared ?? f.ref('team');
      // Not required for validation (the X-Team header may supply it; the block requires it on
      // create), always writable on create, never afterwards, so records cannot change teams.
      def.fields[TEAM_FIELD] = new Field('ref', { ...base.opts, required: false, readOnly: false, hidden: false, writeOnly: false, writableBy: undefined, immutable: true, index: true, filterable: base.opts.filterable ?? ['eq', 'in'] });
      if (def.timestamps) def.indexes = [...def.indexes, { fields: { [TEAM_FIELD]: 1, createdAt: -1 } }];
      scoped.add(def.name);
      return def;
    });

    // The rule functions behind the policy names, with the lowest role each accepts (null: any).
    const ruleRole = new Map();

    /** Lowest role the list policy accepts, when it is made of team rules only; else null (membership). */
    const listRole = (def) => {
      const tokens = def.policy.list ?? [];
      if (!tokens.length || !tokens.every((t) => ruleRole.has(t))) return null;
      const mins = tokens.map((t) => ruleRole.get(t));
      if (mins.includes(null)) return null;
      return mins.reduce((low, r) => (roles.rank(r) > roles.rank(low) ? r : low));
    };

    calm.onService(({ def, service }) => {
      if (def.name === 'team') return teamHooks(service);
      if (!scoped.has(def.name)) return;
      const join = (a, b) => (a && Object.keys(a).length ? { $and: [a, b] } : b);

      // Tenant isolation: AND-ed with the resource's own scope(), for every query of the service.
      const ownScope = service.scope.bind(service);
      service.scope = (ctx = {}) => {
        const own = ownScope(ctx);
        const team = teamScope(ctx);
        if (typeof own?.then === 'function' || typeof team?.then === 'function') return Promise.all([own, team]).then(([a, b]) => join(a, b));
        return join(own, team);
      };

      // A list policy such as 'team:admin' lists only the teams where the caller has that role,
      // so a list never shows records the same caller could not open.
      const list = service.list.bind(service);
      service.list = async (query = {}, ctx = {}) => {
        const min = ctx.system || !ctx.user ? null : listRole(def);
        if (!min) return list(query, ctx);
        const allowed = [...(await memberships(ctx.user))].filter(([, role]) => roles.atLeast(role, min)).map(([id]) => id);
        const filter = query.filter && Object.keys(query.filter).length ? { $and: [query.filter, { [TEAM_FIELD]: { $in: allowed } }] } : { [TEAM_FIELD]: { $in: allowed } };
        return list({ ...query, filter }, ctx);
      };

      const beforeCreate = service.beforeCreate.bind(service);
      service.beforeCreate = async (data, ctx = {}) => {
        let input = data;
        if (input[TEAM_FIELD] == null && ctx.team?.id) input = { ...input, [TEAM_FIELD]: ctx.team.id };
        input = await beforeCreate(input, ctx);
        const team = input[TEAM_FIELD] == null ? null : String(input[TEAM_FIELD]?._id ?? input[TEAM_FIELD]);
        if (!team) throw validationError({ [TEAM_FIELD]: `Pick a team: send "${TEAM_FIELD}" or an ${options.header} header` });
        // Whatever the create policy says, records go only to a team the caller belongs to.
        if (!ctx.system && !(ctx.user && (await memberships(ctx.user)).has(team))) throw forbidden('You are not a member of this team');
        return input;
      };

      const beforeUpdate = service.beforeUpdate.bind(service);
      service.beforeUpdate = async (data, existing, ctx = {}) => {
        const changes = await beforeUpdate(data, existing, ctx);
        // The API already refuses it (immutable field); this covers service calls from your code.
        if (!ctx.system && changes?.[TEAM_FIELD] !== undefined && String(changes[TEAM_FIELD]?._id ?? changes[TEAM_FIELD]) !== String(existing[TEAM_FIELD])) {
          throw validationError({ [TEAM_FIELD]: 'Records cannot move to another team' });
        }
        return changes;
      };
    });

    /**
     * The team filter for one caller. Synchronous when the request already loaded the caller's
     * memberships (the guard below does), otherwise a Promise: app.canRead() and inScope() await
     * it, and core refuses a pending scope where it needs a filter at once, so nothing leaks.
     */
    function teamScope(ctx) {
      if (!ctx.user) return { [TEAM_FIELD]: { $in: [] } }; // nobody outside a team sees team records
      const pick = (mine) => {
        if (ctx.team?.id) return { [TEAM_FIELD]: mine.has(ctx.team.id) ? ctx.team.id : { $in: [] } };
        return { [TEAM_FIELD]: { $in: [...mine.keys()] } };
      };
      const mine = known(ctx.user);
      return mine ? pick(mine) : memberships(ctx.user).then(pick);
    }

    // The team resource: a slug when none is given, and whoever creates a team owns it
    // (POST /api/teams, seeds, your scripts calling service.create(data, { user })).
    function teamHooks(service) {
      const beforeCreate = service.beforeCreate.bind(service);
      service.beforeCreate = async (data, ctx) => {
        const input = await beforeCreate(data, ctx);
        return input.slug ? input : { ...input, slug: await teams.freeSlug(input.name) };
      };
      const afterCreate = service.afterCreate.bind(service);
      service.afterCreate = async (doc, ctx = {}) => {
        await afterCreate(doc, ctx);
        if (!ctx.user?.id) return;
        await teams.Membership.create({ team: doc._id, user: ctx.user.id, role: OWNER });
        teams.forget();
        calm.events.emit('team.created', { team: { id: String(doc._id), name: doc.name, slug: doc.slug }, userId: String(ctx.user.id) });
      };
    }

    // ---- the active team, and memberships loaded once per request ----------------------------

    calm.guard(
      async (ctx) => {
        if (!ctx.user) return;
        const wanted = ctx.req.get(header);
        if (!wanted && !scoped.size) return; // nothing needs memberships up front
        const mine = await memberships(ctx.user);
        if (!wanted) return;
        // Same answer for teams that do not exist: no way to probe team ids.
        if (!isId(wanted) || !mine.has(wanted)) throw forbidden('You are not a member of this team');
        ctx.team = { id: wanted, role: mine.get(wanted) };
      },
      { order: -50 },
    );

    // ---- policies -------------------------------------------------------------------------

    /**
     * Which team a policy is about. undefined: none named; null: named but invalid (refused).
     */
    function targetTeam(ctx) {
      const { doc, req, action } = ctx;
      const asId = (v) => (v === undefined || v === null || v === '' ? undefined : isId(String(v?._id ?? v)) ? String(v?._id ?? v) : null);
      // With a record in hand only its own team counts: a header or body cannot redirect the check.
      if (doc) return req?.calmRoute?.resource === 'team' ? String(doc._id) : (asId(doc[TEAM_FIELD]) ?? null);
      if (req?.params?.teamId !== undefined) return asId(req.params.teamId) ?? null;
      if (action === 'create') {
        const body = ctx.body ?? req?.body;
        if (body && typeof body === 'object' && body[TEAM_FIELD] !== undefined) return typeof body[TEAM_FIELD] === 'string' ? (asId(body[TEAM_FIELD]) ?? null) : null;
      }
      const fromHeader = req?.get?.(header);
      if (fromHeader) return asId(fromHeader) ?? null;
      if (action === 'list' && req?.query?.[TEAM_FIELD] !== undefined) return typeof req.query[TEAM_FIELD] === 'string' ? (asId(req.query[TEAM_FIELD]) ?? null) : null;
      return undefined;
    }

    function rule(min) {
      const fn = async (ctx) => {
        if (!ctx.user) return false;
        const team = targetTeam(ctx);
        // No team named: lists are scoped to the caller's teams anyway, and create refuses (422) a
        // record without a team or (403) in a team the caller is not in. Anything else needs a team.
        if (team === undefined) return (ctx.action === 'list' || ctx.action === 'create') && scoped.has(ctx.req?.calmRoute?.resource);
        if (team === null) return false;
        const role = (await memberships(ctx.user)).get(team);
        return min ? roles.atLeast(role, min) : role !== undefined;
      };
      ruleRole.set(fn, min);
      return fn;
    }
    // A membership is data the exposure matrix cannot invent: signed-in personas show 'custom'.
    const simulate = ({ user }) => (user ? 'custom' : 'deny');
    calm.policy('member', rule(null), { simulate });
    for (const role of roles.list) calm.policy(`team:${role}`, rule(role), { simulate });

    // ---- accounts that go away ----------------------------------------------------------

    const gone = (userId) => userId && calm.app.background(() => teams.userGone(String(userId), { scoped: [...scoped] }));
    calm.on('user.deleted', ({ doc }) => gone(doc?._id));
    calm.on('privacy.account_deleted', ({ userId }) => gone(userId));

    // For seeds, scripts and your own routes:
    //   await app.ext.teams.addMember(teamId, userId, 'admin')
    //   (await app.ext.teams.memberships(user)).get(teamId)   // the user's role, or undefined
    calm.provide('teams', {
      roles: roles.list,
      scoped: () => [...scoped],
      Membership: teams.Membership,
      Invitation: teams.Invitation,
      memberships: teams.memberships,
      roleOf: teams.roleOf,
      create: (user, data) => teams.createTeam(user, data),
      addMember: (teamId, userId, role = options.defaultRole) => teams.addMember(teamId, userId, role),
      removeMember: (teamId, userId) => teams.removeMember(String(teamId), String(userId), null, { reason: 'script' }),
      delete: (teamId) => teams.deleteTeam(String(teamId), { scoped: [...scoped] }),
    });

    // ---- routes -------------------------------------------------------------------------------

    calm.routes(
      (r) => {
        if (!calm.app.auth) {
          calm.log.warn('teams: auth is off (or there is no user resource), so its routes are not registered');
          return;
        }
        const tags = ['teams'];
        const teamDef = () => calm.app.registry.get('team').def;
        const input = (def, body, mode) => validateInput(def, body, { mode, unknownFields: calm.config.unknownFields });
        const inviteRule = `team:${options.inviteRole}`;
        const roleField = () => f.enum(roles.list);
        const teamOf = (ctx) => teams.getTeam(ctx.params.teamId);
        const meta = (ctx) => ({ ip: ctx.req.ip });

        r.post('/', { policy: options.createPolicy, status: 201, summary: 'Create a team (you become its owner)', tags }, async (ctx) => {
          const data = await input(teamDef(), ctx.body, 'create');
          return ctx.reply(await teams.createTeam(ctx.user, data, ctx), { status: 201 });
        });
        r.get('/', { policy: 'authenticated', summary: 'Your teams, with your role in each', tags }, (ctx) => teams.listMine(ctx.user));

        // Static paths before /:teamId.
        r.post(
          '/invitations/accept',
          { policy: 'authenticated', rateLimit: 'auth', summary: 'Join a team with the token from an invitation email', input: { token: f.string().required().max(200) }, tags },
          (ctx) => teams.accept({ token: ctx.body.token }, ctx.user, meta(ctx)),
        );
        r.post(
          '/invitations/lookup',
          { policy: 'public', rateLimit: 'auth', summary: 'What an invitation link is about (team, role, address), before signing in', input: { token: f.string().required().max(200) }, tags },
          (ctx) => teams.lookup(ctx.body.token),
        );
        if (options.verifiedEmailField) {
          const verified = (user) => Boolean(user?.[options.verifiedEmailField]);
          r.get('/invitations', { policy: 'authenticated', summary: 'Invitations to your (verified) email address', tags }, (ctx) => (verified(ctx.user) ? teams.invitationsFor(ctx.user) : []));
          r.post('/invitations/:invitationId/accept', { policy: 'authenticated', summary: 'Accept an invitation to your verified email address', tags }, (ctx) => {
            // An unverified address proves nothing: anybody can sign up with someone else's email.
            if (!verified(ctx.user)) throw forbidden('Verify your email address first, or open the link from the invitation email');
            return teams.accept({ invitationId: ctx.params.invitationId }, ctx.user, meta(ctx));
          });
        }

        r.get('/:teamId', { policy: 'member', summary: 'One of your teams', tags }, async (ctx) =>
          teams.teamView(await teamOf(ctx), (await memberships(ctx.user)).get(ctx.params.teamId), ctx.user),
        );
        r.patch('/:teamId', { policy: 'team:admin', summary: 'Rename a team or change its slug (admins)', tags }, async (ctx) => {
          await teamOf(ctx);
          const data = await input(teamDef(), ctx.body, 'update');
          const doc = await calm.app.service('team').update(ctx.params.teamId, data, { ...ctx, system: true });
          calm.events.emit('team.updated', { team: { id: String(doc._id), name: doc.name, slug: doc.slug }, by: ctx.user.id, changes: Object.keys(data) });
          return teams.teamView(doc, (await memberships(ctx.user)).get(ctx.params.teamId), ctx.user);
        });
        r.delete('/:teamId', { policy: 'team:owner', summary: 'Delete a team, its memberships, invitations and records (owners)', tags }, async (ctx) => {
          await teams.deleteTeam(ctx.params.teamId, { by: ctx.user.id, scoped: [...scoped] });
        });

        r.get('/:teamId/members', { policy: 'member', summary: 'Members of a team and their roles', tags }, async (ctx) => teams.listMembers((await teamOf(ctx))._id));
        r.patch(
          '/:teamId/members/:userId',
          { policy: 'team:admin', summary: "Change a member's role (admins; only owners make owners)", input: { role: roleField().required() }, tags },
          async (ctx) => teams.changeRole((await teamOf(ctx))._id, ctx.params.userId, ctx.body.role, ctx.user),
        );
        r.delete('/:teamId/members/:userId', { policy: 'team:admin', summary: 'Remove a member (admins; only owners remove owners)', tags }, async (ctx) => {
          await teams.removeMember((await teamOf(ctx))._id, ctx.params.userId, ctx.user);
        });
        r.post('/:teamId/leave', { policy: 'member', summary: 'Leave a team (the last owner cannot)', tags }, async (ctx) => {
          await teams.removeMember((await teamOf(ctx))._id, ctx.user.id, ctx.user, { reason: 'left' });
        });
        r.post(
          '/:teamId/transfer',
          { policy: 'team:owner', summary: 'Make another member the owner; you stay as an admin', input: { userId: f.id().required() }, tags },
          async (ctx) => teams.transfer((await teamOf(ctx))._id, ctx.body.userId, ctx.user),
        );

        r.post(
          '/:teamId/invitations',
          { policy: inviteRule, status: 201, summary: 'Invite someone by email', input: { email: f.email().required(), role: roleField() }, tags },
          async (ctx) => ctx.reply(await teams.invite(ctx.params.teamId, ctx.body, ctx.user), { status: 201 }),
        );
        r.get('/:teamId/invitations', { policy: inviteRule, summary: 'Pending invitations of a team', tags }, async (ctx) => teams.listInvitations((await teamOf(ctx))._id));
        r.delete('/:teamId/invitations/:invitationId', { policy: inviteRule, summary: 'Revoke an invitation (its link stops working)', tags }, async (ctx) => {
          await teams.revoke((await teamOf(ctx))._id, ctx.params.invitationId, ctx.user);
        });
        r.post('/:teamId/invitations/:invitationId/resend', { policy: inviteRule, summary: 'Send an invitation again, with a new link', tags }, async (ctx) => {
          try {
            return await teams.resend((await teamOf(ctx))._id, ctx.params.invitationId, ctx.user);
          } catch (err) {
            if (err.retryAfter) ctx.res.setHeader('Retry-After', String(err.retryAfter));
            throw err;
          }
        });
      },
      { prefix: '/teams' },
    );

    // ---- doctor -------------------------------------------------------------------------------

    calm.doctor((app) => {
      const file = 'app/blocks/teams/index.js';
      const findings = [];
      if (!app.auth) findings.push({ level: 'error', id: 'teams-no-auth', title: 'teams needs auth', detail: 'Turn auth on and keep the user resource: teams are made of users.', file });
      if (!app.registry.has('team')) {
        findings.push({ level: 'error', id: 'teams-no-resource', title: 'teams: the team resource is missing', detail: 'Restore app/resources/team/team.resource.js (calm add teams writes it).', file });
        return findings;
      }
      findings.push({
        level: 'info',
        id: 'teams-scoped',
        title: scoped.size ? `Team-scoped resources: ${[...scoped].join(', ')}` : 'No team-scoped resources yet',
        detail: scoped.size
          ? 'Their records are visible only to members of their team, in every route and service call. The exposure matrix shows team rules as custom: cover them with tests (see the teams docs).'
          : "Add team: true to a resource to keep its records inside teams: resource('project', { team: true, fields, policy }).",
      });
      for (const { def, files } of app.registry.values()) {
        if (def.name === 'team' || scoped.has(def.name)) continue;
        const refs = Object.entries(def.fields).filter(([, field]) => field.type === 'ref' && field.opts.ref === 'team').map(([key]) => key);
        if (refs.length) {
          findings.push({
            level: 'warn',
            id: `teams-unscoped-${def.name}`,
            title: `${def.name} references a team but is not team-scoped`,
            detail: `${def.name}.${refs.join(', ')} points at a team, yet its records are not limited to that team's members. Add team: true to the resource (and name the field "${TEAM_FIELD}") if they belong to the team.`,
            file: files?.resource,
          });
        }
      }
      const roleValues = app.registry.get('user')?.def.fields.roles?.opts.of?.opts.values ?? [];
      if (roleValues.includes('member')) {
        findings.push({ level: 'warn', id: 'teams-member-role', title: "A user role is called 'member'", detail: "With the teams block, 'member' in a policy means a member of the record's team, not that user role. Rename the role.", file });
      }
      if (options.inviteRole === roles.lowest) {
        findings.push({ level: 'info', id: 'teams-anyone-invites', title: 'Every team member can invite people', detail: `inviteRole is '${options.inviteRole}'. Invitations still grant at most the inviter's own role.`, file });
      }
      return findings;
    });
  },
});

// Team roles, ordered from most to least powerful: ['owner', 'admin', 'member'] by default,
// with your own roles from options.roles (e.g. ['owner', 'admin', 'billing', 'member', 'viewer']).
//
//  - 'team:<role>' allows that role and every role above it ('team:admin' = admins and owners).
//  - 'member' allows anyone in the team, whatever their role.
//  - You can grant roles up to your own. Only owners grant (or take away) 'owner'.
//  - A role that is no longer configured counts as the lowest one: removing a role from
//    options never promotes anybody.

export const OWNER = 'owner';
export const ADMIN = 'admin';

export function createRoles(list = [OWNER, ADMIN, 'member']) {
  if (!Array.isArray(list) || list[0] !== OWNER || list[1] !== ADMIN || list.length < 3) {
    throw new Error(`teams: options.roles must start with 'owner', 'admin' and list at least one more role, e.g. ['owner', 'admin', 'member']`);
  }
  for (const role of list) {
    if (typeof role !== 'string' || !/^[a-z][a-z0-9-]*$/.test(role)) throw new Error(`teams: role "${role}" must be lowercase letters, digits and -`);
  }
  if (new Set(list).size !== list.length) throw new Error('teams: options.roles has duplicates');

  const rank = (role) => {
    const i = list.indexOf(role);
    return i === -1 ? list.length : i;
  };
  return {
    list: [...list],
    lowest: list.at(-1),
    has: (role) => list.includes(role),
    rank,
    /** True when `role` is `min` or above it. */
    atLeast: (role, min) => role !== undefined && role !== null && rank(role) <= rank(min),
    /** May someone with `actor` give `role` to a person? Up to their own role; owner only by owners. */
    canGrant: (actor, role) => list.includes(role) && (actor === OWNER || (role !== OWNER && rank(role) >= rank(actor))),
  };
}

import { randomBytes } from 'node:crypto';
import { createToken, hashToken, currentRequest, serialize, CalmError, forbidden, notFound, conflict, validationError, tooManyRequests } from '#calm';
import { OWNER, ADMIN } from './roles.js';

// Teams, memberships and invitations: the data and the rules. index.js maps them to routes,
// policies and resource scoping. Every rule that protects a team is enforced here, so routes,
// scripts (app.ext.teams) and your own code all go through the same checks.
//
//  - Memberships are the only source of truth for access. They are read fresh for every
//    request (cached for that request only), so removing someone takes effect on their next call.
//  - A team always keeps at least one owner. Demoting, removing or leaving as the last owner is
//    refused, and a race between two owners is caught after the write and undone.
//  - Invitation tokens are random, stored as SHA-256 hashes, expire, and are claimed with one
//    atomic update, so a link works once. Accepting needs a signed-in user whose account email is
//    the invited address: a forwarded or leaked link is useless to anybody else.

const DAY_MS = 86_400_000;
const KEEP_DAYS = 30; // finished invitations stay this long (audit, "already used" answers), then MongoDB deletes them

export const isId = (s) => typeof s === 'string' && /^[a-f\d]{24}$/i.test(s);
const idOf = (user) => String(user?.id ?? user?._id ?? user);
const slugify = (s) =>
  String(s ?? '')
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 48)
    .replace(/-+$/, '');

const invalidInvitation = () => new CalmError(400, 'INVALID_INVITATION', 'This invitation is invalid or has expired');
const lastOwner = () => new CalmError(409, 'LAST_OWNER', 'A team needs at least one owner. Make someone else an owner first (or delete the team).');

export function createTeams(calm, options, roles) {
  const { Schema } = calm.mongoose;
  const teams = () => calm.app.service('team');
  const users = () => calm.app.model('user');
  const emit = (name, payload) => calm.events.emit(`team.${name}`, payload);
  const security = (name, data) => calm.events.emit(`security.${name}`, data);

  const membershipSchema = new Schema(
    {
      team: { type: Schema.Types.ObjectId, ref: 'team', required: true },
      user: { type: Schema.Types.ObjectId, ref: 'user', required: true },
      role: { type: String, required: true },
      invitedBy: { type: Schema.Types.ObjectId, default: null },
    },
    { collection: 'calm_team_memberships', timestamps: true, versionKey: false },
  );
  membershipSchema.index({ team: 1, user: 1 }, { unique: true }); // one membership per person and team
  membershipSchema.index({ user: 1 });
  membershipSchema.index({ team: 1, role: 1 });
  const Membership = calm.mongoose.model('calmTeamMembership', membershipSchema);

  const invitationSchema = new Schema(
    {
      team: { type: Schema.Types.ObjectId, ref: 'team', required: true, index: true },
      email: { type: String, required: true, lowercase: true, trim: true },
      role: { type: String, required: true },
      tokenHash: { type: String, required: true, unique: true },
      invitedBy: { type: Schema.Types.ObjectId, required: true },
      expiresAt: { type: Date, required: true },
      lastSentAt: { type: Date, required: true },
      sends: { type: Number, default: 1 },
      // `${team}:${email}` while the invitation is open, unset once accepted or revoked: the
      // sparse unique index allows one open invitation per address and team, even across instances.
      openKey: { type: String, default: undefined },
      acceptedAt: { type: Date, default: null },
      acceptedBy: { type: Schema.Types.ObjectId, default: null },
      revokedAt: { type: Date, default: null },
      revokedBy: { type: Schema.Types.ObjectId, default: null },
      purgeAt: { type: Date, required: true },
    },
    { collection: 'calm_team_invitations', timestamps: true, versionKey: false },
  );
  invitationSchema.index({ openKey: 1 }, { unique: true, sparse: true });
  invitationSchema.index({ email: 1, acceptedAt: 1, revokedAt: 1 });
  invitationSchema.index({ purgeAt: 1 }, { expireAfterSeconds: 0 });
  const Invitation = calm.mongoose.model('calmTeamInvitation', invitationSchema);

  // ---- memberships, cached per request ------------------------------------------------

  // request store -> Map(userId -> Map(teamId -> role)). Keyed by the request, never by the user
  // object: long-lived holders of a user (realtime streams) must not keep stale memberships.
  const cache = new WeakMap();

  /** Memberships already loaded in this request, or undefined (scope() needs them synchronously). */
  function known(user) {
    const store = currentRequest();
    return store ? cache.get(store)?.get(idOf(user)) : undefined;
  }

  /** Map(teamId -> role) for a user. One query per user and request. */
  async function memberships(user) {
    const id = idOf(user);
    if (!isId(id)) return new Map();
    const hit = known(user);
    if (hit) return hit;
    const rows = await Membership.find({ user: id }).select('team role').lean();
    const map = new Map(rows.map((m) => [String(m.team), m.role]));
    const store = currentRequest();
    if (store) {
      if (!cache.has(store)) cache.set(store, new Map());
      cache.get(store).set(id, map);
    }
    return map;
  }

  /** After a membership change: whatever this request cached is stale. */
  const forget = () => {
    const store = currentRequest();
    if (store) cache.delete(store);
  };

  /** A role read from the database, never from a cache: used by the rules that change memberships. */
  async function roleOf(teamId, userId) {
    if (!isId(String(teamId)) || !isId(String(userId))) return null;
    return (await Membership.findOne({ team: teamId, user: userId }).select('role').lean())?.role ?? null;
  }

  // ---- teams ----------------------------------------------------------------------------

  /** A team as the API returns it (the team resource's visibility rules) plus your role in it. */
  const teamView = async (team, role, user = null) => ({ ...(await serialize(teams().def, team, { user, registry: calm.app.registry })), role });

  async function getTeam(teamId) {
    const team = isId(teamId) ? await teams().model.findById(teamId).lean() : null;
    if (!team) throw notFound('Team not found');
    return team;
  }

  async function freeSlug(name) {
    const base = slugify(name) || 'team';
    if (!(await teams().model.exists({ slug: base }))) return base;
    for (let i = 0; i < 5; i++) {
      const slug = `${base}-${randomBytes(3).toString('hex')}`;
      if (!(await teams().model.exists({ slug }))) return slug;
    }
    throw conflict('Could not find a free slug, pick one', { slug: 'Already taken' });
  }

  /** The team service's create, with the slug filled in. afterCreate (index.js) makes ctx.user the owner. */
  async function createTeam(user, data, ctx = {}) {
    if (options.maxOwnedTeams) {
      const owned = await Membership.countDocuments({ user: idOf(user), role: OWNER });
      if (owned >= options.maxOwnedTeams) throw new CalmError(409, 'TEAM_LIMIT', `You already own ${owned} teams (the limit is ${options.maxOwnedTeams})`);
    }
    const owner = { ...user, id: idOf(user) };
    const doc = await teams().create(data, { ...ctx, user: owner });
    return teamView(doc, OWNER, owner);
  }

  async function listMine(user) {
    const mine = await memberships(user);
    if (!mine.size) return [];
    const docs = await teams().model.find({ _id: { $in: [...mine.keys()] } }).sort({ name: 1 }).lean();
    return Promise.all(docs.map((t) => teamView(t, mine.get(String(t._id)), user)));
  }

  /**
   * Delete a team: memberships first (access ends at once), then invitations, the records of
   * team-scoped resources (options.deleteRecords) and the team itself.
   */
  async function deleteTeam(teamId, { by = null, scoped = [] } = {}) {
    const team = await getTeam(teamId);
    await Membership.deleteMany({ team: team._id });
    forget();
    await Invitation.deleteMany({ team: team._id });
    const records = {};
    if (options.deleteRecords) {
      for (const name of scoped) records[name] = (await calm.app.model(name).deleteMany({ team: team._id })).deletedCount;
    }
    await teams().model.deleteOne({ _id: team._id });
    emit('deleted', { team: { id: String(team._id), name: team.name, slug: team.slug }, by, records });
  }

  // ---- members -----------------------------------------------------------------------------

  async function listMembers(teamId) {
    const rows = await Membership.find({ team: teamId }).sort({ createdAt: 1 }).lean();
    const people = await users()
      .find({ _id: { $in: rows.map((m) => m.user) } })
      .select(options.showMemberEmails ? 'name email' : 'name')
      .lean();
    const byId = new Map(people.map((u) => [String(u._id), u]));
    return rows.map((m) => {
      const u = byId.get(String(m.user));
      return {
        user: { id: String(m.user), name: u?.name ?? null, ...(options.showMemberEmails ? { email: u?.email ?? null } : {}) },
        role: m.role,
        joinedAt: m.createdAt,
      };
    });
  }

  async function addMember(teamId, userId, role, { invitedBy = null, via = 'script' } = {}) {
    if (!roles.has(role)) throw validationError({ role: `Unknown role. Roles: ${roles.list.join(', ')}` });
    const team = await getTeam(String(teamId));
    try {
      await Membership.create({ team: team._id, user: userId, role, invitedBy });
    } catch (err) {
      if (err?.code === 11000) throw new CalmError(409, 'ALREADY_MEMBER', 'This person is already in the team');
      throw err;
    }
    forget();
    emit('member_added', { team: { id: String(team._id), name: team.name }, userId: String(userId), role, by: invitedBy ? String(invitedBy) : null, via });
    return { teamId: String(team._id), userId: String(userId), role };
  }

  /** Refuse when the change would leave no owner; after the write, undo if a race did. */
  async function keepAnOwner(teamId, change, undo) {
    if ((await Membership.countDocuments({ team: teamId, role: OWNER })) <= 1) throw lastOwner();
    await change();
    if ((await Membership.countDocuments({ team: teamId, role: OWNER })) === 0) {
      await undo();
      throw lastOwner();
    }
  }

  /**
   * Change someone's role. Admins and owners only (the route policy), you grant up to your own
   * role, only owners touch owners, and the last owner cannot be demoted.
   */
  async function changeRole(teamId, userId, role, actor) {
    if (!roles.has(role)) throw validationError({ role: `Unknown role. Roles: ${roles.list.join(', ')}` });
    const actorRole = await roleOf(teamId, idOf(actor));
    const member = isId(userId) ? await Membership.findOne({ team: teamId, user: userId }).lean() : null;
    if (!member) throw notFound('Member not found');
    if (!roles.atLeast(actorRole, ADMIN)) throw forbidden('Only team admins and owners change roles');
    if ((member.role === OWNER || role === OWNER) && actorRole !== OWNER) throw forbidden('Only owners can make or unmake owners');
    if (!roles.canGrant(actorRole, role)) throw forbidden(`You cannot give the ${role} role`);
    if (roles.rank(member.role) < roles.rank(actorRole)) throw forbidden('You cannot change the role of someone above you');
    if (member.role === role) return { userId, role };

    const set = (r) => Membership.updateOne({ _id: member._id }, { $set: { role: r } });
    if (member.role === OWNER) await keepAnOwner(member.team, () => set(role), () => set(OWNER));
    else await set(role);
    forget();
    emit('role_changed', { team: { id: String(teamId) }, userId: String(userId), from: member.role, to: role, by: idOf(actor) });
    return { userId: String(userId), role };
  }

  /**
   * Remove a member (or yourself: reason 'left'). The last owner can neither leave nor be removed.
   * actor null: a trusted call from your code (app.ext.teams.removeMember), no role checks.
   */
  async function removeMember(teamId, userId, actor, { reason = 'removed' } = {}) {
    const member = isId(String(userId)) ? await Membership.findOne({ team: teamId, user: userId }).lean() : null;
    if (!member) throw notFound('Member not found');
    const self = Boolean(actor) && String(userId) === idOf(actor);
    if (actor && !self) {
      const actorRole = await roleOf(teamId, idOf(actor));
      if (!roles.atLeast(actorRole, ADMIN)) throw forbidden('Only team admins and owners remove members');
      if (member.role === OWNER && actorRole !== OWNER) throw forbidden('Only owners can remove owners');
      if (roles.rank(member.role) < roles.rank(actorRole)) throw forbidden('You cannot remove someone above you');
    }
    const remove = () => Membership.deleteOne({ _id: member._id });
    if (member.role === OWNER) await keepAnOwner(member.team, remove, () => Membership.create(member));
    else await remove();
    forget();
    emit('member_removed', { team: { id: String(teamId) }, userId: String(userId), role: member.role, by: actor ? idOf(actor) : null, reason: self ? 'left' : reason });
  }

  /** Make another member an owner; the current owner stays as an admin. Owners only (route policy). */
  async function transfer(teamId, toUserId, actor) {
    const actorId = idOf(actor);
    if ((await roleOf(teamId, actorId)) !== OWNER) throw forbidden('Only owners can transfer ownership');
    if (String(toUserId) === actorId) throw validationError({ userId: 'You already own this team' });
    const target = isId(toUserId) ? await Membership.findOne({ team: teamId, user: toUserId }).lean() : null;
    if (!target) throw validationError({ userId: 'Only members of the team can receive it' });
    // The new owner first, so the team is never without one.
    await Membership.updateOne({ _id: target._id }, { $set: { role: OWNER } });
    await Membership.updateOne({ team: teamId, user: actorId }, { $set: { role: ADMIN } });
    forget();
    const team = { id: String(teamId) };
    if (target.role !== OWNER) emit('role_changed', { team, userId: String(toUserId), from: target.role, to: OWNER, by: actorId, via: 'transfer' });
    emit('role_changed', { team, userId: actorId, from: OWNER, to: ADMIN, by: actorId, via: 'transfer' });
    return { owner: String(toUserId), previousOwner: { userId: actorId, role: ADMIN } };
  }

  // ---- invitations -----------------------------------------------------------------------

  const linkBase = options.linkUrl ?? `${String(calm.config.app.url).replace(/\/$/, '')}/invite`;
  const linkFor = (token) => `${linkBase}${linkBase.includes('?') ? '&' : '?'}token=${encodeURIComponent(token)}`;
  const statusOf = (inv, now = new Date()) =>
    inv.acceptedAt ? 'accepted' : inv.revokedAt ? 'revoked' : inv.expiresAt <= now ? 'expired' : 'pending';
  const openFilter = (extra = {}) => ({ ...extra, acceptedAt: null, revokedAt: null });

  async function invitationView(inv) {
    const by = await users().findById(inv.invitedBy).select('name').lean();
    return {
      id: String(inv._id),
      team: String(inv.team),
      email: inv.email,
      role: inv.role,
      status: statusOf(inv),
      invitedBy: { id: String(inv.invitedBy), name: by?.name ?? null },
      expiresAt: inv.expiresAt,
      lastSentAt: inv.lastSentAt,
      createdAt: inv.createdAt,
    };
  }

  async function sendInvitation(inv, token, inviter) {
    const team = await teams().model.findById(inv.team).select('name').lean();
    if (!team) return;
    const app = calm.config.app.name;
    const who = inviter?.name || 'A teammate';
    const days = options.invitationTtlDays;
    await calm.mailer.send({
      to: inv.email,
      subject: `${who} invited you to ${team.name} on ${app}`,
      text:
        `${who} invited you to join the team ${team.name} on ${app} as ${inv.role}.\n\n` +
        `Open this link to accept (valid for ${days} day${days === 1 ? '' : 's'}, works once). Sign in or create an account with this email address first:\n${linkFor(token)}\n\n` +
        'If you do not want to join, ignore this email.',
      meta: { kind: 'team-invitation', team: String(inv.team), invitationId: String(inv._id), token },
    });
  }

  /** Invite an address. The route policy decides who may invite; here: which role they may give. */
  async function invite(teamId, { email, role = options.defaultRole }, actor) {
    const team = await getTeam(String(teamId));
    const actorRole = await roleOf(team._id, idOf(actor));
    if (!roles.atLeast(actorRole, options.inviteRole)) throw forbidden('You cannot invite people to this team');
    if (!roles.has(role)) throw validationError({ role: `Unknown role. Roles: ${roles.list.join(', ')}` });
    // Inviting is granting: the same rule as changing a role.
    if (!roles.canGrant(actorRole, role)) throw forbidden(`You cannot invite someone as ${role}`);
    const address = String(email).trim().toLowerCase();
    const existing = await users().findOne({ email: address }).select('_id').lean();
    if (existing && (await roleOf(team._id, existing._id))) throw new CalmError(409, 'ALREADY_MEMBER', 'This person is already in the team');

    // A cap on open invitations per team, so a compromised admin account cannot mail-bomb strangers.
    if (options.maxOpenInvitations && (await Invitation.countDocuments(openFilter({ team: team._id }))) >= options.maxOpenInvitations) {
      throw new CalmError(409, 'INVITATION_LIMIT', `This team has ${options.maxOpenInvitations} open invitations. Revoke some first.`);
    }
    const now = new Date();
    const openKey = `${team._id}:${address}`;
    // An expired invitation no longer blocks a new one: it is closed (and cannot be resent).
    await Invitation.updateMany({ openKey, expiresAt: { $lte: now } }, { $set: { revokedAt: now, purgeAt: new Date(now.getTime() + KEEP_DAYS * DAY_MS) }, $unset: { openKey: 1 } });
    const token = createToken('invite');
    const expiresAt = new Date(now.getTime() + options.invitationTtlDays * DAY_MS);
    let inv;
    try {
      inv = await Invitation.create({
        team: team._id,
        email: address,
        role,
        tokenHash: hashToken(token),
        invitedBy: idOf(actor),
        expiresAt,
        lastSentAt: now,
        openKey,
        purgeAt: new Date(expiresAt.getTime() + KEEP_DAYS * DAY_MS),
      });
    } catch (err) {
      if (err?.code === 11000) throw new CalmError(409, 'ALREADY_INVITED', 'This address already has a pending invitation. Resend it instead.');
      throw err;
    }
    const doc = inv.toObject();
    calm.app.background(() => sendInvitation(doc, token, actor));
    emit('invitation_sent', { team: { id: String(team._id), name: team.name }, invitationId: String(doc._id), email: address, role, by: idOf(actor), resend: false });
    return invitationView(doc);
  }

  async function listInvitations(teamId) {
    const list = await Invitation.find(openFilter({ team: teamId })).sort({ createdAt: -1 }).lean();
    return Promise.all(list.map(invitationView));
  }

  async function revoke(teamId, invitationId, actor) {
    if (!isId(invitationId)) throw notFound('Invitation not found');
    const now = new Date();
    const inv = await Invitation.findOneAndUpdate(
      openFilter({ _id: invitationId, team: teamId }),
      { $set: { revokedAt: now, revokedBy: idOf(actor), purgeAt: new Date(now.getTime() + KEEP_DAYS * DAY_MS) }, $unset: { openKey: 1 } },
    ).lean();
    if (!inv) throw notFound('Invitation not found');
    emit('invitation_revoked', { team: { id: String(teamId) }, invitationId: String(inv._id), email: inv.email, by: idOf(actor) });
  }

  /** Send again with a new token (the old link stops working) and a new expiry, once per cooldown. */
  async function resend(teamId, invitationId, actor) {
    if (!isId(invitationId)) throw notFound('Invitation not found');
    const now = new Date();
    const token = createToken('invite');
    const expiresAt = new Date(now.getTime() + options.invitationTtlDays * DAY_MS);
    const cooldown = new Date(now.getTime() - options.resendCooldownSeconds * 1000);
    // One conditional update: concurrent resends cannot both pass the cooldown.
    const inv = await Invitation.findOneAndUpdate(
      // openKey: an expired invitation replaced by a newer one cannot be revived.
      openFilter({ _id: invitationId, team: teamId, openKey: { $exists: true }, lastSentAt: { $lte: cooldown } }),
      { $set: { tokenHash: hashToken(token), expiresAt, lastSentAt: now, purgeAt: new Date(expiresAt.getTime() + KEEP_DAYS * DAY_MS) }, $inc: { sends: 1 } },
      { returnDocument: 'after' },
    ).lean();
    if (!inv) {
      const open = await Invitation.findOne(openFilter({ _id: invitationId, team: teamId, openKey: { $exists: true } })).lean();
      if (!open) throw notFound('Invitation not found');
      const wait = Math.max(1, Math.ceil((open.lastSentAt.getTime() + options.resendCooldownSeconds * 1000 - now.getTime()) / 1000));
      const err = tooManyRequests(`This invitation was sent moments ago. Try again in ${wait} second${wait === 1 ? '' : 's'}.`);
      err.retryAfter = wait;
      throw err;
    }
    calm.app.background(() => sendInvitation(inv, token, actor));
    emit('invitation_sent', { team: { id: String(teamId) }, invitationId: String(inv._id), email: inv.email, role: inv.role, by: idOf(actor), resend: true });
    return invitationView(inv);
  }

  /** What an invitation link is about, for the page that shows it. Open invitations only. */
  async function lookup(token) {
    const inv = await Invitation.findOne({ tokenHash: hashToken(token) }).lean();
    if (!inv || statusOf(inv) !== 'pending') throw invalidInvitation();
    const team = await teams().model.findById(inv.team).select('name slug').lean();
    if (!team) throw invalidInvitation();
    const view = await invitationView(inv);
    return { team: { id: String(team._id), name: team.name, slug: team.slug }, email: inv.email, role: inv.role, invitedBy: { name: view.invitedBy.name }, expiresAt: inv.expiresAt };
  }

  /**
   * Accept an invitation as `user`: by token (anybody holding the link, if their account email is
   * the invited one), or by id (verifiedEmailField: the account's email is verified, no link needed).
   */
  async function accept({ token, invitationId }, user, { ip } = {}) {
    const inv = token ? await Invitation.findOne({ tokenHash: hashToken(token) }).lean() : isId(invitationId) ? await Invitation.findById(invitationId).lean() : null;
    const refuse = (reason, err = invalidInvitation()) => {
      security('invalid_team_invitation', { reason, userId: idOf(user), ip, ...(inv ? { invitationId: String(inv._id), team: String(inv.team) } : {}) });
      return err;
    };
    if (!inv) throw refuse('unknown', token ? invalidInvitation() : notFound('Invitation not found'));
    const email = String(user.email ?? '').toLowerCase();
    // Checked before the claim: the wrong account does not burn the link.
    if (inv.email !== email) {
      throw refuse('wrong_email', token ? new CalmError(403, 'INVITATION_EMAIL', 'This invitation was sent to another email address. Sign in with that address to accept it.') : notFound('Invitation not found'));
    }
    const status = statusOf(inv);
    if (status !== 'pending') throw refuse(status);
    const team = await teams().model.findById(inv.team).lean();
    if (!team) throw refuse('team_deleted');

    // The claim: one atomic update, so an invitation is used once.
    const now = new Date();
    const claimed = await Invitation.findOneAndUpdate(
      openFilter({ _id: inv._id, tokenHash: inv.tokenHash, expiresAt: { $gt: now } }),
      { $set: { acceptedAt: now, acceptedBy: idOf(user), purgeAt: new Date(now.getTime() + KEEP_DAYS * DAY_MS) }, $unset: { openKey: 1 } },
    ).lean();
    if (!claimed) throw refuse('used');

    const current = await roleOf(team._id, idOf(user));
    if (!current) {
      try {
        await addMember(team._id, idOf(user), inv.role, { invitedBy: inv.invitedBy, via: 'invitation' });
      } catch (err) {
        if (err?.code !== 'ALREADY_MEMBER') throw err; // joined meanwhile: keep the role they have
      }
    }
    emit('invitation_accepted', { team: { id: String(team._id), name: team.name }, invitationId: String(inv._id), userId: idOf(user) });
    return teamView(team, current ?? (await roleOf(team._id, idOf(user))), user);
  }

  /** Open invitations for a user's (verified) email address. */
  async function invitationsFor(user) {
    const list = await Invitation.find(openFilter({ email: String(user.email ?? '').toLowerCase(), expiresAt: { $gt: new Date() } })).sort({ createdAt: -1 }).lean();
    const names = new Map((await teams().model.find({ _id: { $in: list.map((i) => i.team) } }).select('name').lean()).map((t) => [String(t._id), t.name]));
    return Promise.all(list.filter((i) => names.has(String(i.team))).map(async (i) => ({ ...(await invitationView(i)), teamName: names.get(String(i.team)) })));
  }

  // ---- accounts that go away -------------------------------------------------------------

  /**
   * A deleted account leaves its teams. Where it was the last owner, the longest-standing admin
   * (else member) becomes owner; a team left with nobody is deleted.
   */
  async function userGone(userId, { scoped = [] } = {}) {
    const rows = await Membership.find({ user: userId }).lean();
    for (const m of rows) {
      await Membership.deleteOne({ _id: m._id });
      emit('member_removed', { team: { id: String(m.team) }, userId: String(userId), role: m.role, by: null, reason: 'account_deleted' });
      if (m.role !== OWNER || (await Membership.exists({ team: m.team, role: OWNER }))) continue;
      const heir =
        (await Membership.findOne({ team: m.team, role: ADMIN }).sort({ createdAt: 1 }).lean()) ??
        (await Membership.findOne({ team: m.team }).sort({ createdAt: 1 }).lean());
      if (heir) {
        await Membership.updateOne({ _id: heir._id }, { $set: { role: OWNER } });
        emit('role_changed', { team: { id: String(m.team) }, userId: String(heir.user), from: heir.role, to: OWNER, by: null, via: 'account_deleted' });
      } else if (await teams().model.exists({ _id: m.team })) {
        await deleteTeam(String(m.team), { scoped });
      }
    }
    await Invitation.updateMany({ invitedBy: userId, ...openFilter() }, { $set: { revokedAt: new Date() }, $unset: { openKey: 1 } });
    forget();
  }

  return {
    Membership,
    Invitation,
